CREATE DATABASE IF NOT EXISTS takekeeper;

CREATE TABLE IF NOT EXISTS takekeeper.takes (production_id String, scene_id String, take_id String, take_number UInt32, camera_id LowCardinality(String), media_ref String, duration_ms UInt64, director_rating UInt8, processing_status LowCardinality(String), recorded_at DateTime64(3, 'UTC'), created_at DateTime64(3, 'UTC') DEFAULT now64(3)) ENGINE=MergeTree ORDER BY (production_id,scene_id,take_number,take_id);
CREATE TABLE IF NOT EXISTS takekeeper.observations (production_id String, scene_id String, take_id String, observation_id String, entity_id String, entity_type LowCardinality(String), property_key LowCardinality(String), normalized_value String, raw_value String, evidence_start_ms UInt64, evidence_end_ms UInt64, confidence Float32, source_type LowCardinality(String), verification_state LowCardinality(String), model_version String, created_at DateTime64(3, 'UTC') DEFAULT now64(3)) ENGINE=MergeTree ORDER BY (production_id,scene_id,take_id,entity_id,property_key,created_at);
CREATE TABLE IF NOT EXISTS takekeeper.continuity_baselines (production_id String, scene_id String, entity_id String, property_key LowCardinality(String), baseline_value String, source_take_id String, approved_by String, approved_at DateTime64(3, 'UTC'), active Bool) ENGINE=MergeTree ORDER BY (production_id,scene_id,entity_id,property_key,active,approved_at);
CREATE TABLE IF NOT EXISTS takekeeper.continuity_findings (production_id String, scene_id String, current_take_id String, finding_id String, entity_id String, property_key LowCardinality(String), baseline_value Nullable(String), observed_value Nullable(String), severity LowCardinality(String), confidence Nullable(Float32), status LowCardinality(String), evidence_start_ms Nullable(UInt64), evidence_end_ms Nullable(UInt64), baseline_source_take_id Nullable(String), created_at DateTime64(3, 'UTC') DEFAULT now64(3)) ENGINE=MergeTree ORDER BY (production_id,scene_id,current_take_id,status,property_key,created_at);
CREATE TABLE IF NOT EXISTS takekeeper.human_decisions (production_id String, decision_id String, finding_id String, actor_id String, decision LowCardinality(String), note String, created_at DateTime64(3, 'UTC') DEFAULT now64(3)) ENGINE=MergeTree ORDER BY (production_id,finding_id,created_at,decision_id);
CREATE TABLE IF NOT EXISTS takekeeper.agent_runs (production_id String, run_id String, intent LowCardinality(String), request_summary String, tool_name LowCardinality(String), query_purpose String, row_count UInt64, elapsed_ms UInt64, result_summary String, status LowCardinality(String), started_at DateTime64(3, 'UTC'), completed_at DateTime64(3, 'UTC')) ENGINE=MergeTree ORDER BY (production_id,started_at,run_id);
